<?php require '../includes/auth.php';require_role('admin');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)post('id');$status=post('status');if($id!==user()['id']&&in_array($status,['active','suspended']))$pdo->prepare('UPDATE users SET status=? WHERE id=?')->execute([$status,$id]);flash('success','User status updated.');redirect('admin/users.php');}$users=$pdo->query("SELECT * FROM users ORDER BY role,name")->fetchAll();$pageTitle='Manage users';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">ADMIN</p><h1>Users</h1></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Change access</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e(ucfirst($u['role']))?></td><td><span class="badge <?=status_class($u['status'])?>"><?=e($u['status'])?></span></td><td><?php if($u['id']!==user()['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$u['id']?>"><select name="status"><option value="active">Activate</option><option value="suspended">Suspend</option></select><button>Save</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php require '../includes/footer.php'; ?>
